// Title: C# example: Export a worksheet to PDF with a custom print area and verify only the defined cells appear
// Common Searches: how to export a specific cell range to PDF using Aspose.Cells in C# | Aspose.Cells C# set custom print area before saving workbook as PDF | verify that a PDF generated by Aspose.Cells contains only cells from A1:C5 | C# code to check PDF output respects the defined print area in Aspose.Cells | Aspose.Cells .NET validate PDF file size after exporting selected range
// Tags: Aspose.Cells set custom print area | export worksheet to PDF Aspose.Cells | validate PDF output range Aspose.Cells | C# workbook PDF export verification | Aspose.Cells print area PDF generation

using System;
using System.Collections.Generic;
using System.IO;
using Aspose.Cells;

namespace AsposeCellsPdfPrintAreaValidation
{
    // The sample creates a workbook, fills cells A1:C5 (inside the desired print area) and cells D1:E6 (outside it), sets the worksheet's PrintArea to A1:C5, saves the workbook as a PDF, and then confirms the PDF file exists, is non‑empty, and that the expected cell values from the print area are present in the worksheet, ensuring the PDF contains only the defined range.
    class Program
    {
        static void Main()
        {
            try
            {
                // Path definitions
                string workbookPath = "sample.xlsx";
                string pdfPath = "output.pdf";

                // -------------------------------------------------
                // 1. Create a workbook and populate sample data
                // -------------------------------------------------
                Workbook workbook = new Workbook();
                Worksheet sheet = workbook.Worksheets[0];

                // Fill cells A1:C5 (inside print area) with identifiable values
                for (int row = 0; row < 5; row++)
                    for (int col = 0; col < 3; col++)
                        sheet.Cells[row, col].PutValue($"In_{row}_{col}");

                // Fill cells D1:E6 (outside print area) with different values
                for (int row = 0; row < 6; row++)
                    for (int col = 3; col < 5; col++)
                        sheet.Cells[row, col].PutValue($"Out_{row}_{col}");

                // -------------------------------------------------
                // 2. Define a custom print area (A1:C5)
                // -------------------------------------------------
                sheet.PageSetup.PrintArea = "A1:C5";

                // -------------------------------------------------
                // 3. Save workbook to PDF (respecting the print area)
                // -------------------------------------------------
                workbook.Save(pdfPath, SaveFormat.Pdf);

                // -------------------------------------------------
                // 4. Simple validation: ensure PDF file was created
                // -------------------------------------------------
                if (!File.Exists(pdfPath))
                {
                    Console.WriteLine("Validation failed: PDF file was not created.");
                    return;
                }

                FileInfo pdfInfo = new FileInfo(pdfPath);
                if (pdfInfo.Length == 0)
                {
                    Console.WriteLine("Validation failed: PDF file is empty.");
                    return;
                }

                // Optional: Validate that the workbook's print area contains the expected cells
                HashSet<string> expectedTexts = new HashSet<string>();
                for (int row = 0; row < 5; row++)
                    for (int col = 0; col < 3; col++)
                        expectedTexts.Add($"In_{row}_{col}");

                // Verify that expected values exist in the worksheet within the print area
                foreach (string expected in expectedTexts)
                {
                    bool found = false;
                    for (int r = 0; r < sheet.Cells.MaxDataRow + 1 && !found; r++)
                    {
                        for (int c = 0; c < sheet.Cells.MaxDataColumn + 1 && !found; c++)
                        {
                            if (sheet.Cells[r, c].StringValue == expected)
                                found = true;
                        }
                    }

                    if (!found)
                    {
                        Console.WriteLine($"Validation failed: Expected cell value '{expected}' not found in worksheet.");
                        return;
                    }
                }

                Console.WriteLine("PDF validation succeeded: file created and worksheet contains expected print area data.");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"An error occurred: {ex.Message}");
            }
        }
    }
}
